-- ---------- 4. Serviços (preço em reais, duração em minutos) ----------
-- Catálogo definido pela equipe em 16/11/2026 (fotos, descrições, preços e
-- durações editados pela tela Serviços e exportados para cá). As fotos ficam
-- em frontend/public/images/servicos/ com o mesmo nome usado abaixo.
INSERT INTO SERVICO (id_clinica, id_categoria, nome, descricao, preco, duracao, ativo, foto_servico)
SELECT @clinica, cat.id_categoria, s.nome, s.descricao, s.preco, s.duracao, TRUE, s.foto
FROM (
    SELECT 'Nail Design' AS categoria, 'Fibra de Vidro' AS nome, 'A técnica de Fibra de Vidro é um método de extensão que proporciona alongamento com aspecto extremamente natural.
Indicada para quem deseja unhas mais longas, resistentes e elegantes, ela se destaca pela durabilidade e acabamento delicado. A estrutura é moldada fio a fio, garantindo leveza, alta resistência e um resultado sofisticado. Ideal para quem busca beleza com performance.' AS descricao, 180.00 AS preco, 180 AS duracao, '/images/servicos/nail-fibra.jpg' AS foto
    UNION ALL SELECT 'Nail Design', 'Banho de Gel', 'O Banho de Gel não é um método de alongamento.
Ele é aplicado sobre a unha natural com o objetivo de fortalecer, proteger e criar uma camada estrutural que reduz quebras e descamações. O gel forma uma barreira resistente que auxilia no crescimento saudável das unhas.
Perfeito para quem deseja manter o comprimento natural com mais firmeza e durabilidade.', 120.00, 150, '/images/servicos/nail-banho.jpg'
    UNION ALL SELECT 'Nail Design', 'Blindagem (Esmaltação em Gel)', 'A blindagem é uma esmaltação em gel aplicada sobre a unha natural, ideal para prolongar a durabilidade do esmalte e manter o brilho impecável por mais tempo.
Durabilidade média: até 20 dias, dependendo dos cuidados e crescimento natural.', 100.00, 120, '/images/servicos/nail-blindagem.jpg'
    UNION ALL SELECT 'Lash Design', 'Volume Brasileiro', 'Uma técnica que equilibra naturalidade e presença.
O Volume Brasileiro combina fios tecnológicos e aplicação estratégica para criar um efeito mais preenchido, mantendo leveza e movimento. Ideal para quem deseja realçar o olhar sem perder a suavidade. Mais definição, sem exageros.
Um olhar naturalmente marcante.', 160.00, 150, '/images/servicos/lash-brasileiro.jpg'
    UNION ALL SELECT 'Lash Design', 'Volume Marrom', 'Perfeito para quem busca sutileza e elegância.
A aplicação com fios marrons proporciona um efeito mais delicado e harmonioso, suavizando o contraste e valorizando traços de forma sofisticada.
Ideal para loiras, ruivas ou para quem prefere um acabamento mais discreto e refinado.
Naturalidade com personalidade.', 165.00, 150, '/images/servicos/lash-marrom.jpg'
    UNION ALL SELECT 'Lash Design', 'Volume Hollywood', 'Intenso, estruturado e impactante.
O Volume Hollywood entrega máximo preenchimento com acabamento uniforme, criando um olhar poderoso e glamouroso.
Indicado para quem ama presença, fotos marcantes e um visual mais expressivo.
Impacto controlado. Elegância com atitude.', 170.00, 150, '/images/servicos/lash-hollywood.jpg'
    UNION ALL SELECT 'Lash Design', 'Volume Inglês', 'Uma técnica que proporciona mais volume e definição, com curvatura estratégica e acabamento marcante.
Entrega um olhar mais evidente e sofisticado, mantendo equilíbrio entre intensidade e harmonia facial.
Ideal para quem deseja destacar os olhos no dia a dia ou em ocasiões especiais.', 180.00, 150, '/images/servicos/lash-ingles.jpg'
    UNION ALL SELECT 'Lash Design', 'Fox Eyes', 'Tendência moderna que cria efeito alongado e levemente puxado no canto externo dos olhos.
A técnica valoriza o formato natural, proporcionando um olhar mais sensual, elegante e contemporâneo.
Perfeita para quem busca um visual mais afilado e estilizado.
Olhar alongado. Expressão marcante.', 190.00, 150, '/images/servicos/lash-fox.jpg'
    UNION ALL SELECT 'Lash Design', 'Sirena', 'Aplicação estratégica que concentra a extensão até aproximadamente 50% a 60% dos cílios naturais.
O resultado é um efeito leve, alongado e extremamente natural, criando um olhar delicado e sofisticado.
Ideal para quem deseja realce sutil com acabamento minimalista.
Menos volume. Mais elegância.', 150.00, 120, '/images/servicos/lash-sirena.jpg'
    UNION ALL SELECT 'Lash Design', 'Efeito Delineado', 'Técnica que posiciona estrategicamente fios mais longos na linha superior, criando a ilusão de um delineado discreto e elegante.
O efeito proporciona mais profundidade ao olhar, destacando o formato dos olhos sem perder leveza.
Ideal para quem deseja definição marcante com acabamento sofisticado.
Um olhar definido, sem precisar de maquiagem.', 210.00, 120, '/images/servicos/lash-delineado.jpg'
    UNION ALL SELECT 'Lash Design', 'Lash Lifting', 'Procedimento que curva e eleva os fios naturais desde a raiz, proporcionando efeito de cílios mais longos e alinhados.
O resultado é um olhar mais aberto e expressivo, mantendo total naturalidade sem extensões.
Durabilidade média de 35 a 45 dias, variando conforme os cuidados e o ciclo natural dos fios.
Beleza natural potencializada.', 140.00, 120, '/images/servicos/lash-lifting.jpg'
    UNION ALL SELECT 'Lash Design', 'Combo: Brow Lamination + Lash Lifting', 'A união perfeita para transformar o olhar de forma completa.
Enquanto o Brow Lamination organiza e estrutura as sobrancelhas, o Lash Lifting eleva e curva os cílios naturais, ampliando a expressão do olhar sem necessidade de extensão.
Um combo pensado para quem deseja praticidade, sofisticação e impacto natural.
Resultado: olhar mais aberto, marcante e harmonioso.', 219.99, 150, '/images/servicos/combo-lash.jpg'
    UNION ALL SELECT 'Sobrancelhas', 'Brow Lamination', 'A técnica de Brow Lamination é um procedimento que foca na organização e alinhamento dos fios das sobrancelhas.
Ela permite criar um efeito de sobrancelhas mais cheias, alinhadas e com aspecto de ''penteadas''.
Ideal para quem tem fios rebeldes, falhas ou deseja um visual mais moderno e expressivo.
A técnica utiliza produtos específicos que suavizam a cutícula do fio, permitindo que ele seja moldado na direção desejada.
Resultado: sobrancelhas impecáveis, com volume e definição natural.', 120.00, 120, '/images/servicos/brow-lamination.jpg'
    UNION ALL SELECT 'Sobrancelhas', 'Design Personalizado', 'Cada sobrancelha é única e o design também deve ser. A técnica é realizada com visagismo, respeitando o formato do rosto, proporções faciais, personalidade e estrutura natural dos fios.
O objetivo não é transformar, mas harmonizar.
Criamos um desenho estratégico que valoriza sua expressão sem perder naturalidade.
Resultado: equilíbrio, leveza e identidade preservada.', 40.00, 60, '/images/servicos/brow-design.jpg'
    UNION ALL SELECT 'Sobrancelhas', 'Design Personalizado com Tintura', 'Além do design estratégico, a tintura intensifica a cor dos fios, proporcionando maior definição e preenchimento visual. Ideal para fios claros, ralos ou com pequenas falhas. Diferente da henna, a tintura pigmenta os fios e não a pele, garantindo um resultado mais natural e sofisticado.
Durabilidade média de até 30 dias nos fios.
Definição sutil, elegante e duradoura.', 60.00, 60, '/images/servicos/brow-tintura.jpg'
    UNION ALL SELECT 'Estética Labial', 'Hidra Gloss', 'Tratamento avançado de hidratação profunda e regeneração labial.
Mais do que estética, ele devolve aos seus lábios aquilo que o tempo, o clima e os hábitos diários retiram: maciez, viço e saúde.
Diferente do preenchimento labial, o foco aqui não é volumizar, mas hidratar profundamente e revitalizar a estrutura dos lábios. O resultado é um efeito visual mais uniforme, viçoso e saudável, o que naturalmente cria a sensação de lábios mais definidos.', 130.00, 90, '/images/servicos/labial-hidra.jpg'
) s
JOIN CATEGORIA cat ON cat.id_clinica = @clinica AND cat.nome = s.categoria;

-- ---------- 5. Horário de funcionamento ----------
-- Segunda a sábado: 09:00–12:00 e 13:00–19:00 (almoço 12h–13h). Domingo fechado.
INSERT INTO HORARIO (id_clinica, dia_semana, hora_inicio, hora_fim, ativo)
SELECT @clinica, d.dia, f.inicio, f.fim, TRUE
FROM (
    SELECT 'SEGUNDA' AS dia UNION ALL SELECT 'TERCA' UNION ALL SELECT 'QUARTA'
    UNION ALL SELECT 'QUINTA' UNION ALL SELECT 'SEXTA' UNION ALL SELECT 'SABADO'
) d
CROSS JOIN (
    SELECT '09:00:00' AS inicio, '12:00:00' AS fim UNION ALL SELECT '13:00:00', '19:00:00'
) f;

